// A shop service written by hand (never generated by gherkin-ai): an HTTP API, an event listener and jobs.
import { Body, ConflictException, Controller, Injectable, Post } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { Cron, Interval } from '@nestjs/schedule';
import axios from 'axios';

export class RegisterCustomerDto {
  email!: string;
}

@Injectable()
export class CustomerService {
  private readonly emails = new Set<string>();

  async register(dto: RegisterCustomerDto) {
    if (this.emails.has(dto.email)) throw new ConflictException('Email already registered');
    this.emails.add(dto.email);
    await axios.post('https://crm.example.com/contacts', { email: dto.email });
    return { email: dto.email, status: 'ACTIVE' };
  }
}

@Controller('customers')
export class CustomersController {
  constructor(private readonly customers: CustomerService) {}

  @Post()
  register(@Body() dto: RegisterCustomerDto) {
    return this.customers.register(dto);
  }
}

@Injectable()
export class NotificationsListener {
  @OnEvent('order.placed')
  sendConfirmation(event: { orderId: string }) {
    const notification = { orderId: event.orderId, status: 'PENDING' };
    notification.status = 'SENT';
    return notification;
  }
}

@Injectable()
export class CartJobs {
  @Cron('0 3 * * *')
  purgeExpiredCarts() {
    const cart = { status: 'OPEN' };
    cart.status = 'EXPIRED';
  }
}

@Injectable()
export class OutboxRelay {
  @Interval(1000)
  relay() {
    const row = { status: 'PENDING' };
    row.status = 'PUBLISHED';
  }
}
